import{c as a,Q as s,j as l,m as n}from"./chunks/framework.DOi4mjdC.js";const d=JSON.parse('{"title":"算子工程编译拓展","description":"","frontmatter":{},"headers":[{"level":1,"title":"算子工程编译拓展","slug":"算子工程编译拓展"},{"level":2,"title":"CMakeLists.txt编写方法","slug":"cmakeliststxt编写方法"},{"level":2,"title":"编译环境选项说明","slug":"编译环境选项说明"},{"level":2,"title":"编译命令说明","slug":"编译命令说明"},{"level":1,"title":"工程根目录下执行","slug":"工程根目录下执行"},{"level":1,"title":"工程根目录下执行","slug":"工程根目录下执行"},{"level":2,"title":"cmake函数说明","slug":"cmake函数说明"}],"relativePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子工程编译拓展.md","filePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子工程编译拓展.md"}'),p={name:"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子工程编译拓展.md"};function e(o,t,i,u,c,g){return s(),l("div",null,[...t[0]||(t[0]=[n(`<h1 id="算子工程编译拓展" tabindex="-1">算子工程编译拓展 <a class="header-anchor" href="#算子工程编译拓展" aria-label="Permalink to &quot;算子工程编译拓展&quot;">​</a></h1><p>使用msOpGen工具创建算子工程时，相关编译脚本被固化在本地，若需使用算子工程提供的新特性（比如支持MC2算子等），需重新运行msOpGen工具生成工程。为了解决开发者因功能更新而频繁重建工程的问题，将算子工程的cmake脚本打包到CANN软件包中。开发者可通过find_package的形式来查找对应的cmake modules包，从而使用算子工程对外提供的cmake函数接口。</p><p>该开发方式下，开发者参考如下工程目录，自行组织算子工程。目录结构与通过msOpGen生成的目录结构类似, 但无需再创建cmake与scripts目录，这些目录被打包至CANN软件包中。以AddCustom算子为例，目录结构如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AddCustom</span></span>
<span class="line"><span>├── CMakeLists.txt              // 算子工程顶层CMakeLists.txt</span></span>
<span class="line"><span>├── CMakePresets.json           // 编译配置项，cmake内置功能，若使能则需3.19及以上cmake版本</span></span>
<span class="line"><span>├── framework                   // AI框架适配时，算子插件实现文件目录</span></span>
<span class="line"><span>├── op_host                     // Host侧实现文件</span></span>
<span class="line"><span>│   ├── add_custom.cpp         // 算子原型注册、Shape推导、Tiling实现等内容文件</span></span>
<span class="line"><span>│   ├── add_custom_tiling.h    // 算子Tiling定义文件</span></span>
<span class="line"><span>│   └── CMakeLists.txt         // Host侧CMakeLists文件</span></span>
<span class="line"><span>├── op_kernel                   // Kernel侧实现文件</span></span>
<span class="line"><span>│   ├── Add</span></span>
<span class="line"><span>│   │   ├── add_custom.cpp    // 算子代码实现文件</span></span>
<span class="line"><span>└   └── CMakeLists.txt         // Kernel侧CMakeLists文件</span></span></code></pre></div><h2 id="cmakelists-txt编写方法" tabindex="-1">CMakeLists.txt编写方法 <a class="header-anchor" href="#cmakelists-txt编写方法" aria-label="Permalink to &quot;CMakeLists.txt编写方法&quot;">​</a></h2><ul><li><p>算子工程顶层CMakeLists.txt</p><ol><li>使用<strong>find_package</strong>找到对应的编译库。</li><li>使用<strong>npu_op_package</strong>设置算子工程的编译产物形态，支持RUN/SHARED/STATIC, 分别对应算子run包形式、算子动态库形式与算子静态库形式，同时，该接口还可配置package（即编译产物）的内容和package的安装位置。</li><li>添加需要进行编译的子目录。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmake_minimum_required(VERSION 3.16.0)            # 指定所需的最低cmake版本号</span></span>
<span class="line"><span>project(opp)</span></span>
<span class="line"><span># 1、使用find_package找到对应的编译库。</span></span>
<span class="line"><span># \${ASCEND_CANN_PACKAGE_PATH}为对应的CANN软件包路径，开发者可直接使用</span></span>
<span class="line"><span>find_package(ASC REQUIRED HINTS \${ASCEND_CANN_PACKAGE_PATH}/compiler/tikcpp/ascendc_kernel_cmake)</span></span>
<span class="line"><span># 2、使用npu_op_package设置算子工程的编译产物形态。</span></span>
<span class="line"><span>set(package_name \${vendor_name})</span></span>
<span class="line"><span>npu_op_package(\${package_name}                     # package name</span></span>
<span class="line"><span>                                                   # RUN模式下会使用该name命名算子部署后的目录，静态库模式下输出产物为lib\${package_name}.a</span></span>
<span class="line"><span>    TYPE RUN                                       # 指定编译产物形态，[RUN|STATIC|SHARED]</span></span>
<span class="line"><span>    CONFIG</span></span>
<span class="line"><span>        ENABLE_SOURCE_PACKAGE True                 # 是否将源码打包到run包中</span></span>
<span class="line"><span>        ENABLE_BINARY_PACKAGE True                 # 是否编译Kernel二进制, SHARED/STATIC模式下必须指定为True, 默认值为True</span></span>
<span class="line"><span>        INSTALL_PATH \${CMAKE_BINARY_DIR}/          # package的安装位置</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>#3、添加需要进行编译的子目录。</span></span>
<span class="line"><span>if(EXISTS \${CMAKE_CURRENT_SOURCE_DIR}/op_host)</span></span>
<span class="line"><span>    add_subdirectory(op_host)                      # 添加子目录op_host进行编译</span></span>
<span class="line"><span>endif()</span></span>
<span class="line"><span>if(EXISTS \${CMAKE_CURRENT_SOURCE_DIR}/op_kernel)</span></span>
<span class="line"><span>    add_subdirectory(op_kernel)                    # 添加子目录op_kernel进行编译</span></span>
<span class="line"><span>endif()</span></span></code></pre></div></li><li><p>Host侧CMakeLists.txt</p><ol><li>使用<strong>npu_op_code_gen</strong>生成aclnn单算子调用代码、入图所需的原型定义代码等。</li><li>单算子调用场景，使用<strong>npu_op_library</strong>编译aclnn单算子调用库。</li><li>算子入图场景，使用<strong>npu_op_library</strong>编译算子入图所需的算子原型库。</li><li>使用<strong>npu_op_library</strong>编译Tiling相关库。</li><li>使用<strong>npu_op_package_add</strong>添加上述Host侧库至对应package中。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>aux_source_directory(\${CMAKE_CURRENT_SOURCE_DIR} ops_srcs)</span></span>
<span class="line"><span>#1、使用npu_op_code_gen生成aclnn单算子调用代码、入图所需的原型定义代码等。</span></span>
<span class="line"><span>npu_op_code_gen(</span></span>
<span class="line"><span>     SRC \${ops_srcs}                                                           # Host侧实现文件集合</span></span>
<span class="line"><span>     PACKAGE \${package_name}                                                   # 与npu_op_package的package_name对应</span></span>
<span class="line"><span>     COMPILE_OPTIONS -g                                                        # 编译选项</span></span>
<span class="line"><span>     OUT_DIR \${ASCEND_AUTOGEN_PATH}                                            # 指定生成文件的保存路径</span></span>
<span class="line"><span>     JOIN_OP_DEF False    # 可选参数，默认为False。设置为False，编译CMakePreset.json中设置的AI处理器型号对应的算子；设置成True，则编译CMakePreset.json和算子原型注册中共有的AI处理器型号对应的算子。 </span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>#2、单算子调用场景，使用npu_op_library编译aclnn单算子调用库。</span></span>
<span class="line"><span>file(GLOB autogen_aclnn_src \${ASCEND_AUTOGEN_PATH}/aclnn_*.cpp)                # 将通过npu_op_code_gen生成的aclnn相关源文件添加至源文件列表中</span></span>
<span class="line"><span>                                                                               </span></span>
<span class="line"><span>set_source_files_properties(\${autogen_aclnn_src} PROPERTIES GENERATED TRUE)    # 设置对应的文件属性为编译过程中生成的文件</span></span>
<span class="line"><span>npu_op_library(cust_opapi ACLNN                                                # 指定library名称与类型，以及参与编译的源文件</span></span>
<span class="line"><span>     \${autogen_aclnn_src}</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>target_compile_options(cust_opapi PRIVATE                                      # 为对应library添加编译选项，与通用的cmake语法一致</span></span>
<span class="line"><span>     -fvisibility=hidden</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#3、算子入图场景，使用npu_op_library编译算子入图所需的算子原型库。</span></span>
<span class="line"><span>file(GLOB proto_src \${ASCEND_AUTOGEN_PATH}/op_proto.cc)                        # 将通过npu_op_code_gen生成的原型定义相关源文件添加至源文件列表中</span></span>
<span class="line"><span>set_source_files_properties(\${proto_src} PROPERTIES GENERATED TRUE)            # 设置对应的文件属性为编译过程中生成的文件</span></span>
<span class="line"><span>npu_op_library(cust_op_proto GRAPH                                             # 指定library名称与类型，以及参与编译的源文件</span></span>
<span class="line"><span>     \${ops_srcs}</span></span>
<span class="line"><span>     \${proto_src}</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>target_compile_options(cust_op_proto PRIVATE                                   # 为对应library添加编译选项，与通用的cmake语法一致</span></span>
<span class="line"><span>     -fvisibility=hidden</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#4、使用npu_op_library编译Tiling相关库。</span></span>
<span class="line"><span>file(GLOB fallback_src \${ASCEND_AUTOGEN_PATH}/fallback_*.cpp)                  # 将通过npu_op_code_gen生成的Tiling相关源文件添加至源文件列表中</span></span>
<span class="line"><span>                                                                               # 若算子配置了EnableFallBack会生成该文件</span></span>
<span class="line"><span>set_source_files_properties(\${fallback_src} PROPERTIES GENERATED TRUE)         # 设置对应的文件属性为编译过程中生成的文件</span></span>
<span class="line"><span>npu_op_library(cust_optiling  TILING                                           # 指定library名称与类型，以及参与编译的源文件</span></span>
<span class="line"><span>     \${ops_srcs}</span></span>
<span class="line"><span>     \${fallback_src}</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>target_compile_options(cust_optiling PRIVATE                                   # 为对应library添加编译选项，与通用的cmake语法一致</span></span>
<span class="line"><span>     -fvisibility=hidden</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#5、使用npu_op_package_add添加上述Host侧库到对应package中。</span></span>
<span class="line"><span>npu_op_package_add(\${package_name}                                             # 与npu_op_package的package_name对应</span></span>
<span class="line"><span>     LIBRARY                                                                   # 添加Host侧相关library，library名称与前述步骤的library名称对应 </span></span>
<span class="line"><span>          cust_optiling</span></span>
<span class="line"><span>          cust_opapi</span></span>
<span class="line"><span>          cust_op_proto</span></span>
<span class="line"><span>)</span></span></code></pre></div></li><li><p>Kernel侧CMakeLists.txt</p><ol><li><p>使用<strong>npu_op_kernel_options</strong>添加算子编译选项。支持的编译选项可参考<a href="./算子包编译/算子工程编译.html#table151052168302">编译选项</a>。</p></li><li><p>使用<strong>npu_op_kernel_sources</strong>指定算子特定目录与编译源文件。</p><ul><li>若算子的源码文件没有平铺在SRC_BASE目录（通过npu_op_kernel_library设置）下，可以通过KERNEL_DIR指定特定目录。</li><li>若算子的Kernel实现cpp文件需要自定义命名，需同时指定OP_TYPE（算子类型）和KERNEL_FILE（Kernel实现cpp文件名），以配置两者之间的对应关系。不配置时，Kernel实现cpp文件名和OpType之间需满足<a href="./算子原型定义.html">转换规则</a>。</li></ul></li><li><p>使用<strong>npu_op_kernel_library</strong>编译Kernel库。</p></li><li><p>使用<strong>npu_op_package_add</strong>添加上述Kernel侧库到对应package中。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#1、使用npu_op_kernel_options添加算子编译选项。</span></span>
<span class="line"><span>npu_op_kernel_options(ascendc_kernels ALL OPTIONS --save-temp-files -g)# 为算子添加编译选项</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#2、使用npu_op_kernel_sources指定算子特定目录与编译源文件。</span></span>
<span class="line"><span>npu_op_kernel_sources(ascendc_kernels                                  # 对应的Kernel库名称，与npu_op_kernel_library保持一致</span></span>
<span class="line"><span>    OP_TYPE AddCustom                                                  # 若算子的Kernel实现cpp文件需要自定义命名，需配置算子类型</span></span>
<span class="line"><span>    KERNEL_DIR ./Add                                                   # 将KERNEL_DIR目录与SRC_BASE目录进行拼接，作为Kernel实现cpp文件所在的目录</span></span>
<span class="line"><span>    COMPUTE_UNIT Ascendxxxyy                                           # 设置KERNEL_FILE在Ascendxxxyy型号生效</span></span>
<span class="line"><span>    KERNEL_FILE add_custom.cpp                                         # 若算子的Kernel实现cpp文件需要自定义命名，需配置Kernel实现cpp文件名</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#3、使用npu_op_kernel_library编译Kernel库。</span></span>
<span class="line"><span>npu_op_kernel_library(ascendc_kernels                                  # Kernel库名称</span></span>
<span class="line"><span>    SRC_BASE \${CMAKE_SOURCE_DIR}/op_kernel/                            # 指定kernel侧源码的根目录</span></span>
<span class="line"><span>    TILING_LIBRARY cust_optiling                                       # 指定依赖的Tiling库</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>#4、添加kernel侧library到package</span></span>
<span class="line"><span>npu_op_package_add(\${package_name}                                     # 与npu_op_package的package_name对应</span></span>
<span class="line"><span>    LIBRARY ascendc_kernels                                            # 添加Kernel侧相关library，library名称与前述步骤的library名称对应</span></span>
<span class="line"><span>)</span></span></code></pre></div></li></ul><h2 id="编译环境选项说明" tabindex="-1">编译环境选项说明 <a class="header-anchor" href="#编译环境选项说明" aria-label="Permalink to &quot;编译环境选项说明&quot;">​</a></h2><p>下表列出了供用户配置和使用的编译环境选项：</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>暂不支持设置Release、Debug版本相关选项。</li><li>暂不支持交叉编译相关选项。</li></ul></div><p><strong>表 1</strong> 编译环境选项</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.72%&quot;&gt;&lt;p&gt;类型&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.47%&quot;&gt;&lt;p&gt;环境选项&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.64%&quot;&gt;&lt;p&gt;默认值&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.17%&quot;&gt;&lt;p&gt;说明&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.72%&quot;&gt;&lt;p&gt;STRING&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.47%&quot;&gt;&lt;p&gt;vendor_name&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.64%&quot;&gt;&lt;p&gt;customize&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.17%&quot;&gt;&lt;p&gt;标识自定义算子所属厂商的名称。建议开发者自行指定所属厂商名称，避免和其他厂商提供的算子包冲突。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.72%&quot;&gt;&lt;p&gt;STRING&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.47%&quot;&gt;&lt;p&gt;ASCEND_COMPUTE_UNIT&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.64%&quot;&gt;&lt;p&gt;-&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.17%&quot;&gt;&lt;p&gt;&lt;span&gt;AI处理器&lt;/span&gt;型号。编译对应型号的package。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.72%&quot;&gt;&lt;p&gt;PATH&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.47%&quot;&gt;&lt;p&gt;ASCEND_AUTOGEN_PATH&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.64%&quot;&gt;&lt;p&gt;&lt;CMAKE_BINARY_DIR&gt;/autogen&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.17%&quot;&gt;&lt;p&gt;通过npu_op_code_gen生成的aclnn单算调用、入图所需算子原型库等源文件存放路径。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.72%&quot;&gt;&lt;p&gt;BOOL&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.47%&quot;&gt;&lt;p&gt;ENABLE_SOURCE_PACKAGE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.64%&quot;&gt;&lt;p&gt;TRUE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.17%&quot;&gt;&lt;p&gt;是否开启源码编译。&lt;/p&gt; &lt;p&gt;如果使用npu_op_package配置了源码和二进制编译相关配置，npu_op_package配置的优先级更高。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.72%&quot;&gt;&lt;p&gt;BOOL&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.47%&quot;&gt;&lt;p&gt;ENABLE_BINARY_PACKAGE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.64%&quot;&gt;&lt;p&gt;TRUE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.17%&quot;&gt;&lt;p&gt;是否开启二进制编译。&lt;/p&gt; &lt;p&gt;package的类型配置为SHARED或STATIC时，必须指定为TRUE。&lt;/p&gt; &lt;p&gt;如果使用npu_op_package配置了源码和二进制编译相关配置，npu_op_package配置的优先级更高。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.72%&quot;&gt;&lt;p&gt;BOOL&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.47%&quot;&gt;&lt;p&gt;ASCEND_SKIP_FAILED_COMPUTE_UNIT&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.64%&quot;&gt;&lt;p&gt;FALSE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.17%&quot;&gt;&lt;p&gt;该参数用于控制部分AI处理器型号对应的算子编译失败时，是否跳过失败并继续编译其他型号的算子。&lt;/p&gt; &lt;p&gt;例如：当npu_op_code_gen函数中JOIN_OP_DEF参数设置成False时，可能比设置成True编译更多AI处理器型号的算子。在此过程中，如果某些型号的算子编译失败，可以使用此参数控制是否跳过这些失败，从而不影响其他AI处理器型号的算子编译。&lt;/p&gt; &lt;p&gt;设置成True为跳过失败，跳过失败不影响其他AI处理器型号对应算子的编译流程；设置成False，遇到失败会影响其他AI处理器型号对应算子的编译流程。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.72%&quot;&gt;&lt;p&gt;PATH&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.47%&quot;&gt;&lt;p&gt;ASCEND_CANN_PACKAGE_PATH&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.64%&quot;&gt;&lt;p&gt;-&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.17%&quot;&gt;&lt;p&gt;CANN软件包路径，默认情况下用户无需配置。开发者可以在编写cmake文件时直接使用。&lt;/p&gt; &lt;p&gt;路径示例如下：/usr/local/Ascend/cann。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>上述编译环境选项可通过两种方式进行配置：</p><ul><li><p>支持直接通过set命令进行设置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># CMakeLists.txt直接使用</span></span>
<span class="line"><span>set(vendor_name &quot;customize&quot;)</span></span>
<span class="line"><span>set(ASCEND_COMPUTE_UNIT &quot;ascendxxxyy&quot;)</span></span></code></pre></div></li><li><p>通过CMakePresets.json进行设置，若通过该方式设置，则需要安装3.19及以上的cmake。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;version&quot;: 1,</span></span>
<span class="line"><span>    &quot;cmakeMinimumRequired&quot;: {</span></span>
<span class="line"><span>        &quot;major&quot;: 3,</span></span>
<span class="line"><span>        &quot;minor&quot;: 19,</span></span>
<span class="line"><span>        &quot;patch&quot;: 0</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;configurePresets&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;name&quot;: &quot;default&quot;,</span></span>
<span class="line"><span>            &quot;displayName&quot;: &quot;Default Config&quot;,</span></span>
<span class="line"><span>            &quot;description&quot;: &quot;Default build using Unix Makefiles generator&quot;,</span></span>
<span class="line"><span>            &quot;generator&quot;: &quot;Unix Makefiles&quot;,</span></span>
<span class="line"><span>            &quot;binaryDir&quot;: &quot;\${sourceDir}/build_out&quot;,</span></span>
<span class="line"><span>            &quot;cacheVariables&quot;: {</span></span>
<span class="line"><span>                &quot;ASCEND_COMPUTE_UNIT&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;STRING&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;ascendxxxyy&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;vendor_name&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;STRING&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;customize&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>然后使用如下命令进行构建，根据--preset指定的preset进行编译。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Shell环境中cmake构建编译</span></span>
<span class="line"><span>cmake -S . -B build_out --preset=default // 在当前目录(.)中寻找CMakePresets.json</span></span>
<span class="line"><span>// 若用户cmake版本小于3.19.0，则不支持--preset构建选项，该场景下，使用如下构建编译命令</span></span>
<span class="line"><span>\${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。</span></span>
<span class="line"><span>opts=$(python3 $INSTALL_DIR/tools/tikcpp/ascendc_kernel_cmake/fwk_modules/util/preset_parse.py $script_path/CMakePresets.json)</span></span>
<span class="line"><span>cmake -S . -B &quot;$BUILD_DIR&quot; $opts</span></span></code></pre></div></li></ul><h2 id="编译命令说明" tabindex="-1">编译命令说明 <a class="header-anchor" href="#编译命令说明" aria-label="Permalink to &quot;编译命令说明&quot;">​</a></h2><p>package的类型配置为RUN时，可参考如下编译命令进行编译，使用cmake的pack能力生成run包。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 工程根目录下执行</span></span>
<span class="line"><span>mkdir -p build_out</span></span>
<span class="line"><span>rm -rf build_out/*</span></span>
<span class="line"><span>cmake -S . -B build_out --preset=default</span></span>
<span class="line"><span>cmake --build build_out --target binary -j$(nproc)</span></span>
<span class="line"><span>cmake --build build_out --target package -j$(nproc)</span></span></code></pre></div><p>package的类型配置为SHARED或STATIC时，可参考如下编译命令进行编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 工程根目录下执行</span></span>
<span class="line"><span>mkdir -p build_out</span></span>
<span class="line"><span>rm -rf build_out/*</span></span>
<span class="line"><span>cmake -S . -B build_out --preset=default</span></span>
<span class="line"><span>cmake --build build_out --target binary -j$(nproc)</span></span>
<span class="line"><span>cmake --build build_out --target install -j$(nproc)</span></span></code></pre></div><h2 id="cmake函数说明" tabindex="-1">cmake函数说明 <a class="header-anchor" href="#cmake函数说明" aria-label="Permalink to &quot;cmake函数说明&quot;">​</a></h2><p>提供如下cmake函数供开发者使用：</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.21%&quot;&gt;&lt;p&gt;类型&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;34.160000000000004%&quot;&gt;&lt;p&gt;接口&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.63%&quot;&gt;&lt;p&gt;功能&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; rowspan=&quot;2&quot; valign=&quot;top&quot; width=&quot;16.21%&quot;&gt;&lt;p&gt;package&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;34.160000000000004%&quot;&gt;&lt;p&gt;&lt;a href=&quot;#li030816192116&quot;&gt;npu_op_package&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.63%&quot;&gt;&lt;p&gt;创建一个package。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;&lt;a href=&quot;#li1671193919294&quot;&gt;npu_op_package_add&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;将目标或文件添加到package中。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; rowspan=&quot;5&quot; valign=&quot;top&quot; width=&quot;16.21%&quot;&gt;&lt;p&gt;library&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;34.160000000000004%&quot;&gt;&lt;p&gt;&lt;a href=&quot;#li25281233402&quot;&gt;npu_op_library&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.63%&quot;&gt;&lt;p&gt;创建Host侧库。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;&lt;a href=&quot;#li16862112335017&quot;&gt;npu_op_kernel_library&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;创建Kernel侧库。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;&lt;a href=&quot;#li15612655800&quot;&gt;npu_op_kernel_options&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;添加Kernel目标编译选项。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;&lt;a href=&quot;#li178055111110&quot;&gt;npu_op_kernel_sources&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;描述Kernel目标的源码信息。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;&lt;a href=&quot;#li121991221837&quot;&gt;npu_op_device_tiling_library&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;创建Device侧Tiling库。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.21%&quot;&gt;&lt;p&gt;其他&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;34.160000000000004%&quot;&gt;&lt;p&gt;&lt;a href=&quot;#li184365230416&quot;&gt;npu_op_code_gen&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.63%&quot;&gt;&lt;p&gt;执行代码生成过程，生成aclnn单算子调用代码和入图所需的原型定义代码。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><ol><li><p>npu_op_package</p><p>创建一个package。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npu_op_package(&lt;package_name&gt; TYPE &lt;type&gt; [CONFIG] [ENABLE_SOURCE_PKG &lt;value&gt;] [ENABLE_BINARY_PACKAGE &lt;value&gt;] [INSTALL_PATH &lt;path&gt;])</span></span></code></pre></div><p>参数说明如下：</p><ul><li>&lt;package_name&gt;：必选，package的名称。</li><li>TYPE &lt;type&gt;：必选，package的类型，取值为RUN、SHARED、STATIC。分别对应算子run包形式、算子动态库形式与算子静态库形式。</li><li>[CONFIG]：可选，用于配置package的内容和安装位置。 <ul><li>[ENABLE_SOURCE_PKG &lt;value&gt;]：可选，是否将源码打包到package中，默认为True。</li><li>[ENABLE_BINARY_PACKAGE &lt;value&gt;] ：可选，是否将二进制文件打包到package中，默认为True。</li><li>[INSTALL_PATH &lt;path&gt;]：可选，指定包的安装路径，默认为CMAKE_BINARY_DIR。</li><li>[ENABLE_CPACK &lt;value&gt;] ：可选，是否打包，默认为True。对于用户需要定制打包的场景，可以设置为False，配置为False的情况下直接在&lt;path&gt;路径下生成编译产物，不会打包为run包。</li></ul></li></ul></li><li><p>npu_op_package_add</p><p>将目标或文件添加到package中。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 添加目标</span></span>
<span class="line"><span>npu_op_package_add(&lt;package_name&gt; LIBRARY &lt;target_name1&gt; [&lt;target_name2&gt;...] ) </span></span>
<span class="line"><span># 添加文件，仅给run包模式使用</span></span>
<span class="line"><span>npu_op_package_add(&lt;package_name&gt; FILES &lt;file_name1&gt; [&lt;file_name2&gt;...] [TYPE &lt;target_type&gt;] [PACKAGE_PATH &lt;pkg_path&gt;])</span></span></code></pre></div><p>参数说明如下：</p><ul><li><p>&lt;package_name&gt;：必选，package的名称。</p></li><li><p>LIBRARY：必选，指定需要添加到package中的目标名称。</p><ul><li>&lt;target_name1&gt; [&lt;target_name2&gt;...]：必选，目标名称列表。</li></ul></li><li><p>FILES：必选，指定需要添加到package中的文件名称。</p><ul><li>&lt;file_name1&gt; [&lt;file_name2&gt;...]：必选，文件名称列表。</li></ul></li><li><p>[TYPE &lt;target_type&gt;]：可选，指定文件类型，将文件安装到对应的目录中，取值为ACLNN、GRAPH。配置为ACLNN，会将文件打包至run包目录下aclnn单算子调用头文件所在目录，配置为GRAPH，会将文件打包至run包目录下入图原型定义头文件目录下。</p></li><li><p>[PACKAGE_PATH &lt;pkg_path&gt;]：可选，指定文件在包中的相对路径位置。TYPE和PACKAGE_PATH参数互斥，即只能选择其中一个进行配置。</p></li></ul></li><li><p>npu_op_library</p><p>创建Host侧库。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npu_op_library(&lt;library_name&gt; TYPE &lt;library_type&gt; &lt;files&gt;)</span></span></code></pre></div><p>参数说明如下：</p><ul><li><p>&lt;library_name&gt;：必选，Host侧库的名称。</p></li><li><p>TYPE &lt;library_type&gt;：必选，Host库的类型，可选值为TILING、ACLNN、GRAPH、TF_PLUGIN。</p><ul><li>TILING，Tiling相关库。</li><li>ACLNN，aclnn单算子调用库。</li><li>GRAPH，算子入图所需的算子原型库。</li><li>TF_PLUGIN，TensorFlow框架适配相关库。</li></ul></li><li><p>&lt;files&gt;：必选，设置参与编译的源文件。</p></li></ul></li><li><p>npu_op_kernel_library</p><p>创建Kernel侧库。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npu_op_kernel_library(&lt;target_name&gt; SRC_BASE &lt;path&gt; TILING_LIBRARY &lt;tiling_target&gt;)</span></span></code></pre></div><p>参数说明如下：</p><ul><li>&lt;target_name&gt;：必选，目标的名称。</li><li>SRC_BASE &lt;path&gt;：必选，指定Kernel源码的base目录，要求配置绝对路径。比如示例中的op_kernel目录的绝对路径。</li><li>TILING_LIBRARY &lt;tiling_target&gt;：必选，指定依赖的Tiling目标。</li></ul></li><li><p>npu_op_kernel_options</p><p>添加Kernel目标编译选项。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npu_op_kernel_options(&lt;target_name&gt; &lt;op_type&gt; [COMPUTE_UNIT &lt;soc_version&gt;] OPTIONS …)</span></span></code></pre></div><p>参数说明如下：</p><ul><li><p>&lt;target_name&gt;：必选，目标的名称。</p></li><li><p>&lt;op_type&gt;：必选，定义配置生效的范围，取值为ALL、OP_TYPE。ALL表示对所有算子生效，OP_TYPE表示对特定算子生效。</p></li><li><p>[COMPUTE_UNIT &lt;soc_version&gt;]：可选，用于设置算子在具体AI处理器型号上的编译选项，不填写该选项时默认对所有型号生效。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>针对如下产品：在安装AI处理器的服务器执行npu-smi info命令进行查询，获取Name信息。实际配置值为AscendName，例如Name取值为xxxyy，实际配置值为Ascendxxxyy。&lt;br/&gt;&lt;br/&gt; Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> Atlas 200I/500 A2 推理产品<br> Atlas 推理系列产品<br> Atlas 训练系列产品&lt;br/&gt;&lt;br/&gt;</li><li>针对&lt;term&gt;Atlas A3 训练系列产品&lt;/term&gt;/&lt;term&gt;Atlas A3 推理系列产品&lt;/term&gt;，在安装AI处理器的服务器执行npu-smi info -t board -i id -c chip_id命令进行查询，获取Chip Name和NPU Name信息，实际配置值为Chip Name_NPU Name。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。其中：&lt;br/&gt;id：设备id，通过npu-smi info -l命令查出的NPU ID即为设备id。&lt;br/&gt; chip_id：芯片id，通过npu-smi info -m命令查出的Chip ID即为芯片id。&lt;br/&gt;&lt;br/&gt;</li><li>针对Ascend 950PR/Ascend 950DT，在安装AI处理器的服务器执行npu-smi info -t board -i id命令进行查询，获取Chip Name和NPU Name信息，实际配置值为Chip Name_NPU Name。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。&lt;br/&gt; 其中：id为设备id，通过npu-smi info -l命令查出的NPU ID即为设备id。</li></ul></div></li><li><p>OPTION...： 必选，传递给编译器的编译选项。</p></li></ul></li><li><p>npu_op_kernel_sources</p><p>描述Kernel目标的源码信息，包括设置算子的Kernel实现文件和源码路径等。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npu_op_kernel_sources(&lt;target_name&gt; [OP_TYPE &lt;op_type&gt;] [KERNEL_DIR &lt;path&gt;] [COMPUTE_UNIT &lt;soc_version&gt;] [KERNEL_FILE &lt;file&gt;])</span></span></code></pre></div><p>参数说明如下：</p><ul><li><p>&lt;target_name&gt;：必选，目标的名称。</p></li><li><p>[OP_TYPE &lt;op_type&gt;]：可选，算子类型，必须与KERNEL_FILE同时存在。</p></li><li><p>[KERNEL_DIR &lt;path&gt;]：可选，指定Kernel源码相对于SRC_BASE的相对路径。</p><p>若算子的源码文件没有平铺在SRC_BASE目录（通过npu_op_kernel_library设置）下，可以通过KERNEL_DIR指定特定目录。</p></li><li><p>[COMPUTE_UNIT &lt;soc_version&gt;] ：可选，设置KERNEL_FILE在&lt;soc_version&gt;型号生效。默认KERNEL_FILE对所有型号生效。</p></li><li><p>[KERNEL_FILE &lt;file&gt;]：可选，指定算子入口的Kernel实现文件名。</p><p>若算子的Kernel实现cpp文件需要自定义命名，需同时指定OP_TYPE（算子类型）和KERNEL_FILE（Kernel实现cpp文件名），以配置两者之间的对应关系。不配置时，Kernel实现cpp文件名和OpType之间需满足<a href="./算子原型定义.html">转换规则</a>。</p></li></ul></li><li><p>npu_op_device_tiling_library</p><p>创建Device侧Tiling库。使用该选项时，package的类型仅支持配置为RUN（run包模式）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npu_op_device_tiling_library(&lt;target_name&gt; &lt;type&gt; &lt;files&gt;)</span></span></code></pre></div><p>参数说明如下：</p><ul><li>&lt;target_name&gt;：必选，目标的名称。</li><li>&lt;type&gt;：必选，指定Tiling产物的类型。支持取值为SHARED、STATIC。</li><li>&lt;files&gt;：必选，指定Tiling源码文件。</li></ul></li><li><p>npu_op_code_gen</p><p>执行代码生成过程，生成aclnn单算子调用代码和入图所需的原型定义代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npu_op_code_gen(SRC &lt;src_files&gt; OUT_DIR &lt;output_dir&gt; PACKAGE &lt;pkg_name&gt; [COMPILE_OPTIONS ...] [JOIN_OP_DEF ...])</span></span></code></pre></div><p>参数说明如下：</p><ul><li>SRC &lt;src_files&gt;：必选，参与代码生成的源文件范围。</li><li>OUT_DIR &lt;output_dir&gt;：必选，生成代码的输出路径。</li><li>PACKAGE &lt;pkg_name&gt;：必选，指定生成代码的package名称。</li><li>[COMPILE_OPTIONS ...]：可选，自定义编译过程中的编译选项。</li><li>[JOIN_OP_DEF ...]：可选，默认为False。设置为False，编译CMakePreset.json中设置的AI处理器型号对应的算子；设置成True，则编译CMakePreset.json和算子原型注册中共有的AI处理器型号对应的算子。</li></ul></li></ol>`,22)])])}const _=a(p,[["render",e]]);export{d as __pageData,_ as default};
